INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die ISO-27001 eine gesetzliche Vorschrift?', 2, '[{"text": "Nein", "correct": true, "because": "Freiwilliger Standard"}, {"text": "Ja", "correct": false, "because": "Keine gesetzliche Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt die ISO-27001?', 3, '[{"text": "Informationssicherheit", "correct": true, "because": "Schützt Daten und Systeme"}, {"text": "Maximale Datenspeicherung", "correct": false, "because": "Nicht primär"}, {"text": "Kostensenkung", "correct": false, "because": "Sicherheit im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zur ISO-27001?', 5, '[{"text": "Risikomanagement", "correct": true, "because": "Kern des Standards"}, {"text": "Sicherheitsmaßnahmen", "correct": true, "because": "Schutz implementieren"}, {"text": "Farbschema", "correct": false, "because": "Nicht sicherheitsrelevant"}, {"text": "UI-Design", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) ISO-27001 ist ein Zertifizierungsstandard. b) Sie gilt nur für IT-Firmen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gilt für alle Branchen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der ISO-27001-Umsetzung?', 4, '[{"text": "Risikoanalyse", "correct": false, "because": "Zentraler Bestandteil"}, {"text": "Kontrollmaßnahmen", "correct": false, "because": "Pflicht zur Absicherung"}, {"text": "Typografie", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ISO-27001 auch physische Sicherheit abdeckt?', 2, '[{"text": "Ja", "correct": true, "because": "Umfasst alle Sicherheitsaspekte"}, {"text": "Nein", "correct": false, "because": "Nicht nur IT"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist für die ISO-27001-Zertifizierung zentral?', 3, '[{"text": "ISMS", "correct": true, "because": "Informationssicherheitsmanagementsystem"}, {"text": "Datenbankgröße", "correct": false, "because": "Irrelevant"}, {"text": "Schnelle Server", "correct": false, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte sind für ISO-27001 erforderlich?', 5, '[{"text": "Risikobewertung", "correct": true, "because": "Identifiziert Bedrohungen"}, {"text": "Kontrollen implementieren", "correct": true, "because": "Schutzmaßnahmen umsetzen"}, {"text": "Maximale Datensammlung", "correct": false, "because": "Nicht vorgeschrieben"}, {"text": "Visuelle Gestaltung", "correct": false, "because": "Kein Schutzfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) ISO-27001 verbessert Sicherheitsmanagement. b) Sie ist nur für große Firmen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gilt für alle Größen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die ISO-27001?', 4, '[{"text": "Sicherheitsrichtlinien", "correct": false, "because": "Teil des ISMS"}, {"text": "Auditplanung", "correct": false, "because": "Pflicht für Zertifizierung"}, {"text": "Grafikdesign", "correct": true, "because": "Kein Sicherheitsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ISO-27001 nur für IT-Sicherheit?', 2, '[{"text": "Nein", "correct": true, "because": "Umfasst Informationssicherheit allgemein"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bereiche deckt ISO-27001 ab?', 4, '[{"text": "Physische Sicherheit", "correct": true, "because": "Teil des Standards"}, {"text": "IT-Sicherheit", "correct": true, "because": "Kernbereich"}, {"text": "Serverleistung", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ISO-27001 nur einmalig nötig ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kontinuierliche Verbesserung"}, {"text": "Ja", "correct": false, "because": "Regelmäßige Audits"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der ISO-27001-Umsetzung?', 3, '[{"text": "Risikomanagement", "correct": true, "because": "Kern des ISMS"}, {"text": "Schnelle Zertifizierung", "correct": false, "because": "Qualität zählt"}, {"text": "Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) ISO-27001 fordert ein ISMS. b) Es ist gesetzlich vorgeschrieben.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Freiwilliger Standard"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen unterstützt ISO-27001?', 5, '[{"text": "Zugriffskontrollen", "correct": true, "because": "Schützt Informationen"}, {"text": "Notfallmanagement", "correct": true, "because": "Reaktion auf Vorfälle"}, {"text": "Unbegrenzte Speicherung", "correct": false, "because": "Nicht vorgeschrieben"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der ISO-27001 unwichtig?', 3, '[{"text": "Sicherheitskontrollen", "correct": false, "because": "Kern des Standards"}, {"text": "Risikoüberprüfung", "correct": false, "because": "Pflicht"}, {"text": "Animationseffekte", "correct": true, "because": "Kein Sicherheitsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss ISO-27001 regelmäßig geprüft werden?', 3, '[{"text": "Ja", "correct": true, "because": "Audits für Zertifizierung"}, {"text": "Nein", "correct": false, "because": "Kontinuierliche Überwachung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ISO-27001 international anerkannt ist?', 2, '[{"text": "Ja", "correct": true, "because": "Globaler Standard"}, {"text": "Nein", "correct": false, "because": "Weltweit genutzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element wähle ich für ISO-27001?', 4, '[{"text": "Risikobeurteilung", "correct": true, "because": "Basis für Sicherheitsmaßnahmen"}, {"text": "Zufällige Datensammlung", "correct": false, "because": "Nicht vorgeschrieben"}, {"text": "Grafisches Design", "correct": false, "because": "Kein Schutzfokus"}]');
